package com.aoo.bcg.wordcard;import com.aoo.bcg.gamespi.*;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;class LczpNineStageAcceptanceTest{@Test void authorityNineStages(){LczpGameProvider p=new LczpGameProvider();LczpSession s=(LczpSession)p.roomFactory().create(new RoomCreationContext(49001,10,Map.of("redCuo",true))).requireAuthoritativeSession();StatePayload base=StatePayload.copyOf(s.authoritativeState());s.execute(c(1,1,20,"join",Map.of()));s.execute(c(2,1,20,"ready",Map.of()));Map<String,Object>v=s.execute(c(3,0,10,"start",Map.of())).body().asMap();Map<?,?>seat=(Map<?,?>)((Map<?,?>)v.get("seats")).get(0);int card=(Integer)((List<?>)seat.get("cards")).getFirst();s.execute(c(4,0,10,"operation",Map.of("operation","OUT","type","SINGLE","cards",List.of(card))));assertEquals(1,s.viewFor(20).get("currentSeat"));s.execute(c(5,1,20,"operation",Map.of("operation","PASS")));StatePayload replay=p.eventReplayProvider().orElseThrow().replay(base,s.events());assertEquals(s.authoritativeState(),replay.asMap());assertEquals(s.viewFor(20),p.restoreAuthoritativeSession(replay).orElseThrow().viewFor(20));assertTrue(s.invariantViolations().isEmpty());assertEquals(44,LczpRules.deck().size());}@Test void cardTypesAndAtomicProvider(){assertEquals(LczpRules.Type.LONG,LczpRules.classify(LczpRules.Type.LONG,List.of(1001,1002,1003,1004)).type());assertEquals(0,ServiceLoader.load(GameProvider.class).stream().filter(x->x.type()==LczpGameProvider.class).count());}private static GameCommandRequest c(long n,int seat,long p,String a,Map<String,Object>payload){return new GameCommandRequest("wordcard.lczp.dispatch","l"+n,n,49001,0,"1.0.0",String.valueOf(p),seat,Map.of("action",a,"payload",payload));}}
